from typing import List, Dict, Any

class EmbeddingRequest:
    def __init__(self, texts: List[str], model: str = "text-embedding-ada-002"):
        self.texts = texts
        self.model = model

class EmbeddingResponse:
    def __init__(self, data: List[Dict[str, Any]], model: str):
        self.data = data
        self.model = model

    def get_embeddings(self) -> List[List[float]]:
        return [d["embedding"] for d in self.data]

class CombinedEmbeddingResult:
    def __init__(self, text: str, embedding: List[float]):
        self.text = text
        self.embedding = embedding

import os
import openai
from typing import List, Dict, Any
from embeddings_models import EmbeddingRequest, EmbeddingResponse

class EmbeddingsClient:
    def __init__(self):
        self.client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    def create_embeddings(self, request: EmbeddingRequest) -> EmbeddingResponse:
        response = self.client.embeddings.create(input=request.texts, model=request.model)
        return EmbeddingResponse(
            data=[{"embedding": r.embedding, "index": r.index, "object": r.object} for r in response.data],
            model=response.model
        )

import numpy as np
from typing import List
from embed_text import embed_text

def cosine_similarity(embedding1: List[float], embedding2: List[float]) -> float:
    dot_product = np.dot(embedding1, embedding2)
    norm_a = np.linalg.norm(embedding1)
    norm_b = np.linalg.norm(embedding2)
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot_product / (norm_a * norm_b)

def similarity_score(text1: str, text2: str) -> float:
    embedding_result1 = embed_text(text1)
    embedding_result2 = embed_text(text2)
    return cosine_similarity(embedding_result1.embedding, embedding_result2.embedding)

import os
import openai
from typing import List, Dict, Any

class EmbeddingJobResult:
    def __init__(self, job_id: str, texts_processed: int, status: str, errors: List[str] = None):
        self.job_id = job_id
        self.texts_processed = texts_processed
        self.status = status
        self.errors = errors if errors is not None else []

def summarize_embedding_job(job_result: EmbeddingJobResult) -> str:
    client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    prompt = f"Summarize the embedding job with ID {job_result.job_id}. " \
             f"It processed {job_result.texts_processed} texts and its status is {job_result.status}. "
    if job_result.errors:
        prompt += f"There were errors: {', '.join(job_result.errors)}."
    else:
        prompt += "There were no errors."

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes embedding job results."},
            {"role": "user", "content": prompt}
        ]
    )
    return response.choices[0].message.content
